/**
 * The Astrometrics Studio's galleries: every starter, object type and shape
 * has a picture (generated by `npm run astro:pictures`), there are none left
 * over, every type has a gallery group and a valid sample scene; starters
 * have a one-line summary, and the gallery helpers turn a starter's params
 * into form fields (real sizes in named units) and say what it adds.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readdirSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { STARTERS } from '../../src/core/astrometrics/starters/index.js';
import { starterPicture, typePicture, shapePicture, TYPE_GROUPS, starterParamSchema, starterParamChoices, starterParamValues, starterAdds, PICTURE_BASE } from '../../src/editor/dialogs/astro-studio/starter-gallery.js';
import { fieldKind } from '../../src/editor/dialogs/astro-studio/schema-fields.js';
import { OBJECT_TYPES, GRID_SHAPES, VOLUME_SHAPES, IMAGE_SHAPES, NEBULA_SHAPES } from '../../src/core/astrometrics/names.js';
import { TYPE_SAMPLES, SHAPE_SAMPLES } from '../../src/core/astrometrics/object-samples.js';
import { getSchemaEntries } from '../../scripts/lib/card-schemas.js';
import { buildRegistries } from '../../scripts/lib/registries.js';
import { createConfigValidator } from '../../scripts/lib/config-validator.js';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
// the source (the build copies it to custom_components/lcards/images/)
const DIR = join(ROOT, 'src/assets/images/astro-studio');
const fileOf = (/** @type {string} */ url) => join(DIR, url.slice(PICTURE_BASE.length));

const SHAPES = { grid: GRID_SHAPES, volume: VOLUME_SHAPES, image: IMAGE_SHAPES, nebula: NEBULA_SHAPES };

test('every starter, type and shape has its picture (npm run astro:pictures), and no picture is left over', () => {
  const urls = [
    ...STARTERS.map((s) => starterPicture(s.id)),
    ...OBJECT_TYPES.map((t) => typePicture(t)),
    ...Object.entries(SHAPES).flatMap(([t, list]) => list.map((sh) => shapePicture(t, sh)))
  ];
  const missing = urls.filter((u) => !existsSync(fileOf(u)));
  assert.deepEqual(missing, [], 'run npm run astro:pictures for these');
  const wanted = new Set(urls.map((u) => u.slice(PICTURE_BASE.length)));
  const stray = readdirSync(DIR).filter((f) => /^(starter|type|shape)-/.test(f) && !wanted.has(f));
  assert.deepEqual(stray, []);
});

test('every type is in a gallery group and has a sample; every shape a sample; each sample is a valid card', async () => {
  // every type in exactly one group
  assert.deepEqual(TYPE_GROUPS.flatMap((g) => g.types).sort(), [...OBJECT_TYPES].sort());
  assert.deepEqual(Object.keys(TYPE_SAMPLES).sort(), [...OBJECT_TYPES].sort());
  for (const [t, list] of Object.entries(SHAPES)) assert.deepEqual(Object.keys(SHAPE_SAMPLES[t]), [...list], t);
  const checker = createConfigValidator({ entries: getSchemaEntries(), registries: await buildRegistries() });
  const samples = [
    ...Object.entries(TYPE_SAMPLES).map(([t, s]) => [`type ${t}`, s]),
    ...Object.entries(SHAPE_SAMPLES).flatMap(([t, m]) => Object.entries(m).map(([sh, s]) => [`shape ${t} ${sh}`, s]))
  ];
  for (const [name, s] of samples) {
    const config = { type: 'custom:lcards-astrometrics-card', ...(s.points ? { points: s.points } : {}), objects: s.objects, camera: { view: 'picture', views: { picture: s.camera } } };
    assert.deepEqual(checker.validateConfig(config).map((i) => `${i.code} ${i.path}: ${i.message}`), [], name);
  }
});

test('every starter has a one-line summary for its tile', () => {
  for (const s of STARTERS) {
    assert.ok(s.summary, `${s.id} has no summary`);
    assert.ok(s.summary.length <= 80, `${s.id}: summary is ${s.summary.length} characters`);
    assert.ok(!/[.—]$/.test(s.summary), `${s.id}: a summary is a phrase, not a sentence`);
  }
});

test('starter params become form fields: numbers, point pickers, dropdowns and text', () => {
  for (const s of STARTERS) {
    const schema = starterParamSchema(s);
    for (const p of s.params) {
      const kind = fieldKind(schema[p.key], p.key);
      const want = p.type === 'number' ? 'number' : p.type === 'point' ? 'pointRef' : p.options?.length && !p.custom ? 'enum' : 'text';
      assert.equal(kind, want, `${s.id}.${p.key}`);
      assert.equal(schema[p.key]['x-ui-hints'].label, p.label);
    }
  }
  const planet = STARTERS.find((s) => s.id === 'planet');
  assert.ok(planet);
  assert.ok(starterParamChoices(planet).look.includes('gas_giant'));
  assert.equal(starterParamValues(planet, { moons: 4 }).moons, 4);
  assert.equal(starterParamValues(planet).orbit, 40);
  // real sizes where the units are named
  assert.equal(starterParamValues(planet, {}, 'au').orbit, 1);
  assert.equal(starterParamValues(planet, {}, 'km').radius, 6370);
  assert.equal(starterParamValues(planet, { radius: 7 }, 'km').radius, 7);
});

test('what a starter adds, in words', () => {
  const planet = STARTERS.find((s) => s.id === 'planet');
  assert.ok(planet);
  assert.match(starterAdds(planet), /^\d+ points, \d+ objects$/);
  assert.notEqual(starterAdds(planet, { moons: 0 }), starterAdds(planet, { moons: 4 }));
});
